  // --- CHECK FOR UPDATES & REFRESH ACTION ---
  const handleCheckForUpdates = async () => {
    if (isCheckingUpdate) return;
    setIsCheckingUpdate(true);
    showToast('æ­£åœ¨æª¢æ¸¬ä¼ºæœå™¨èˆ‡æœ€æ–°ç³»çµ±ç‰ˆæœ¬...', 'info');

    try {
      // 1. åŒæ­¥é›²ç«¯æœ€æ–°è³‡æ–™
      await fetchAllData(true);

      // 2. æª¢æ¸¬é é¢ Script æª”æ¡ˆæ˜¯å¦æœ‰ Build æ–°ç‰ˆæœ¬
      const currentScripts = Array.from(document.querySelectorAll('script'))
        .map(s => s.src)
        .filter(Boolean)
        .sort()
        .join(',');

      const res = await fetch(`/?nocache=${Date.now()}`, { cache: 'no-store' });
      const htmlText = await res.text();

      const parser = new DOMParser();
      const doc = parser.parseFromString(htmlText, 'text/html');
      const fetchedScripts = Array.from(doc.querySelectorAll('script'))
        .map(s => s.src)
        .filter(Boolean)
        .sort()
        .join(',');

      const hasNewVersion = fetchedScripts !== '' && currentScripts !== '' && fetchedScripts !== currentScripts;

      if (hasNewVersion) {
        showToast('ğŸ‰ æª¢æ¸¬åˆ°ç³»çµ±æ–°ç‰ˆæœ¬ï¼æ­£åœ¨è‡ªå‹•æ›´æ–°ä¸¦é‡æ–°è¼‰å…¥...', 'success');
        setTimeout(() => {
          window.location.reload();
        }, 1200);
      } else {
        showToast('âœ… æ•¸æ“šèˆ‡ç³»çµ±ç¨‹å¼çš†å·²ç‚ºæœ€æ–°ç‰ˆæœ¬ï¼Œå³å°‡é‡æ–°æ•´ç†å®ŒæˆåŒæ­¥ï¼', 'success');
        setTimeout(() => {
          window.location.reload();
        }, 800);
      }
    } catch (err) {
      console.error("Check for updates error:", err);
      showToast('æ•¸æ“šå·²åŒæ­¥å®Œæˆï¼Œç³»çµ±æ­£åœ¨é‡æ–°æ•´ç†...', 'info');
      setTimeout(() => {
        window.location.reload();
      }, 800);
    } finally {
      setIsCheckingUpdate(false);
    }
  };

  // Category counts for quotation directory tabs
  const activeQuotesCount = useMemo(() => quotations.filter(q => q.status !== 'completed' && q.status !== 'cancelled').length, [quotations]);
  const completedQuotesCount = useMemo(() => quotations.filter(q => q.status === 'completed').length, [quotations]);
  const cancelledQuotesCount = useMemo(() => quotations.filter(q => q.status === 'cancelled').length, [quotations]);

  // --- SEARCH AND FILTER LOGIC ---
  const filteredQuotations = useMemo(() => {
    const filtered = quotations.filter(quote => {
      // Filter by category tab first (active / completed / cancelled)
      if (contractCategoryTab === 'active') {
        if (quote.status === 'completed' || quote.status === 'cancelled') {
          return false;
        }
      } else if (contractCategoryTab === 'completed') {
        if (quote.status !== 'completed') {
          return false;
        }
      } else if (contractCategoryTab === 'cancelled') {
        if (quote.status !== 'cancelled') {
          return false;
        }
      }

      const matchStatus = statusFilter === 'all' || quote.status === statusFilter;
      
      let matchInternalNumber = true;
      if (internalNumberFilter === 'd_only') {
        matchInternalNumber = !!quote.internalNumber && quote.internalNumber.toUpperCase().includes('D');
      } else if (internalNumberFilter === 'a_only') {
        matchInternalNumber = !!quote.internalNumber && quote.internalNumber.toUpperCase().includes('A');
      }

      const matchAssignedTo = assignedToFilter === 'all' || quote.assignedTo === assignedToFilter;

      const lowerQuery = searchQuery.trim().toLowerCase();
      const assignedUser = accountsList.find(a => a.username === quote.assignedTo);
      const assignedName = assignedUser ? assignedUser.displayName : (quote.assignedTo || '');

      const matchSearch = !lowerQuery || 
        (quote.customerName || '').toLowerCase().includes(lowerQuery) ||
        (quote.phone || '').includes(lowerQuery) ||
        (quote.address || '').toLowerCase().includes(lowerQuery) ||
        (quote.id || '').toLowerCase().includes(lowerQuery) ||
        (quote.internalNumber && (quote.internalNumber || '').toLowerCase().includes(lowerQuery)) ||
        (quote.assignedTo || '').toLowerCase().includes(lowerQuery) ||
        assignedName.toLowerCase().includes(lowerQuery);

      return matchStatus && matchInternalNumber && matchAssignedTo && matchSearch;
    });

    if (internalNumberSort === 'asc') {
      return [...filtered].sort((a, b) => {
        const valA = a.internalNumber || '';
        const valB = b.internalNumber || '';
        return valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' });
      });
    } else if (internalNumberSort === 'desc') {
      return [...filtered].sort((a, b) => {
        const valA = a.internalNumber || '';
        const valB = b.internalNumber || '';
        return valB.localeCompare(valA, undefined, { numeric: true, sensitivity: 'base' });
      });
    }

    return filtered;
  }, [quotations, searchQuery, statusFilter, contractCategoryTab, internalNumberFilter, assignedToFilter, internalNumberSort, accountsList]);

  // --- GROUPING BY INTERNAL NUMBER INTO FOLDERS ---
  const toggleFolder = (internalNumber: string) => {
    setExpandedFolders(prev => ({
      ...prev,
      [internalNumber]: !prev[internalNumber]
    }));
  };

  const groupedQuotations = useMemo(() => {
    if (!folderGroupingEnabled) {
      return filteredQuotations.map(quote => ({
        type: 'single' as const,
        quote,
        id: quote.id
      }));
    }

    const map = new Map<string, Quotation[]>();
    filteredQuotations.forEach(quote => {
      const rawKey = (quote.internalNumber || '').trim();
      if (rawKey) {
        if (!map.has(rawKey)) {
          map.set(rawKey, []);
        }
        map.get(rawKey)!.push(quote);
      }
    });

    const result: (
      | { type: 'single'; quote: Quotation; id: string }
      | { type: 'folder'; internalNumber: string; quotes: Quotation[]; id: string }
    )[] = [];

    const processedFolders = new Set<string>();

    filteredQuotations.forEach(quote => {
      const rawKey = (quote.internalNumber || '').trim();
      if (!rawKey) {
        result.push({ type: 'single', quote, id: quote.id });
      } else {
        const folderQuotes = map.get(rawKey) || [];
        if (folderQuotes.length >= 2) {
          if (!processedFolders.has(rawKey)) {
            processedFolders.add(rawKey);
            result.push({
              type: 'folder',
              internalNumber: rawKey,
              quotes: folderQuotes,
              id: `folder-${rawKey}`
            });
          }
        } else {
          result.push({ type: 'single', quote, id: quote.id });
        }
      }
    });

    return result;
  }, [filteredQuotations, folderGroupingEnabled]);

